'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies, compare } = require('./src/semver');

// 1. Numeric (not lexicographic) newest-first ordering
assert.deepEqual(resolve({ widget: { '1.9.0': {}, '1.10.0': {}, '1.8.3': {} } }, { widget: '^1.0.0' }), { widget: '1.10.0' });

// 2. Backtracking must undo a retracted choice's constraints (no phantom conflicts)
//    a@2 needs c>=2 (missing) -> fall back to a@1 which allows c@1
const reg2 = {
  a: { '2.0.0': { c: '>=2.0.0' }, '1.0.0': { c: '<2.0.0' } },
  b: { '1.0.0': {} },
  c: { '1.0.0': {} },
};
assert.deepEqual(resolve(reg2, { a: '*', b: '*' }), { a: '1.0.0', b: '1.0.0', c: '1.0.0' });

// 3. Constraints from a retracted sibling must not poison a later choice
//    x picks u@2 (deps nothing), y's dep forces u<2 -> backtrack u to 1.x
const reg3 = {
  x: { '1.0.0': { u: '*' } },
  y: { '1.0.0': { u: '<2.0.0' } },
  u: { '2.0.0': {}, '1.5.0': {} },
};
assert.deepEqual(resolve(reg3, { x: '*', y: '*' }), { x: '1.0.0', u: '1.5.0', y: '1.0.0' });

// 4. First-found DFS: newest working combination, not just newest of each
const reg4 = {
  a: { '2.0.0': { c: '^2.0.0' }, '1.0.0': { c: '^1.0.0' } },
  c: { '2.0.0': { d: '>=5.0.0' }, '1.0.0': {} },
  d: { '1.0.0': {} },
};
assert.deepEqual(resolve(reg4, { a: '*' }), { a: '1.0.0', c: '1.0.0' });

// 5. Cycles terminate
const cyc = {
  a: { '1.0.0': { b: '^1.0.0' } },
  b: { '1.0.0': { a: '^1.0.0' } },
};
assert.deepEqual(resolve(cyc, { a: '*' }), { a: '1.0.0', b: '1.0.0' });
const selfBad = { a: { '1.0.0': { a: '>=2.0.0' } } };
assert.equal(resolve(selfBad, { a: '*' }), null);

// 6. Long chain far beyond the old 4096 cap, iterative (no stack overflow)
const N = 200000;
const chain = {};
for (let i = 0; i < N; i += 1) chain['p' + i] = { '1.0.0': { ['p' + (i + 1)]: '^1.0.0' } };
chain['p' + N] = { '1.0.0': {} };
const chainResult = resolve(chain, { p0: '^1.0.0' });
assert.equal(Object.keys(chainResult).length, N + 1);
assert.equal(chainResult['p' + N], '1.0.0');

// 7. Wide Cartesian space: conflict discovered late must prune early, not enumerate
const wide = {};
for (let i = 0; i < 40; i += 1) {
  wide['w' + i] = { '1.0.0': {}, '2.0.0': {}, '3.0.0': {} };
}
wide.w0 = { '1.0.0': { z: '^1.0.0' }, '2.0.0': {}, '3.0.0': {} };
wide.z = { '1.0.0': {} };
const wideResult = resolve(wide, Object.fromEntries(Object.keys(wide).filter(k => k !== 'z').map(k => [k, '*'])));
assert.equal(wideResult.w0, '3.0.0');

// 8. Missing package -> null; genuinely unsatisfiable -> null
assert.equal(resolve({}, { ghost: '*' }), null);
assert.equal(resolve({ a: { '1.0.0': { b: '^1.0.0' } }, b: { '2.0.0': {} } }, { a: '*' }), null);

// 9. Empty root
assert.deepEqual(resolve({}, {}), {});

// 10. Eager validation, including unreachable entries
assert.throws(() => resolve({ bad: { '1.0': {} }, ok: { '1.0.0': {} } }, { ok: '*' }), TypeError);
assert.throws(() => resolve({ bad: { '1.0.0': { x: '~~1.0.0' } } }, {}), TypeError);
assert.throws(() => resolve([], {}), TypeError);
assert.throws(() => resolve({ a: { '1.0.0': [] } }, {}), TypeError);

// 11. Null-prototype maps accepted; inputs not mutated; __proto__-safe result keys
const np = Object.create(null); np['1.0.0'] = Object.create(null);
const regNp = Object.create(null); regNp.m = np;
assert.deepEqual(resolve(regNp, { m: '*' }), { m: '1.0.0' });
const proto = { '__proto__': { '1.0.0': {} } };
const protoReg = Object.create(null); protoReg['__proto__'] = { '1.0.0': {} };
const protoResult = resolve(protoReg, { '__proto__': '*' });
assert.equal(Object.getPrototypeOf(protoResult), Object.prototype);
assert.equal(Object.prototype['__proto__'] === '1.0.0', false);
assert.equal(protoResult['__proto__'], '1.0.0');
const frozenRoot = { m: '^1.0.0' };
const before = JSON.stringify(reg2);
resolve(reg2, { a: '*' });
assert.equal(JSON.stringify(reg2), before);

// 12. semver caret rules
assert.equal(satisfies('0.2.9', '^0.2.3'), true);
assert.equal(satisfies('0.3.0', '^0.2.3'), false);
assert.equal(satisfies('0.0.3', '^0.0.3'), true);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('1.4.0', '^1.2.3'), true);
assert.equal(satisfies('2.0.0', '^1.2.3'), false);
assert.equal(satisfies('1.3.0', '~1.2.3'), false);
assert.equal(satisfies('1.2.9', '~1.2.3'), true);
assert.equal(compare('1.10.0', '1.9.0'), 1);

console.log('all verification checks passed');

