      const upper = operator === '~' ? [base[0], base[1] + 1, 0]
        : base[0] !== 0 ? [base[0] + 1, 0, 0]
        : base[1] !== 0 ? [0, base[1] + 1, 0]
        : [0, 0, base[2] + 1];
      return version => compareParts(version, base) >= 0 && compareParts(version, upper) < 0;
    }
    return version => {
      const order = compareParts(version, base);
      switch (operator) {
